// Package lru implements a fixed-capacity least-recently-used cache with
// O(1) expected time for every operation.
package lru

// nilIndex marks the absence of a node in the recency list or free list.
const nilIndex = -1

type node struct {
	key, value string
	prev, next int32 // towards more / less recently used
}

// Cache is an LRU cache mapping string keys to string values. Entries live in
// a node pool linked into an intrusive doubly linked recency list, so the
// steady state performs no per-entry allocation beyond the map itself.
//
// The zero value is not usable; create caches with New.
type Cache struct {
	index    map[string]int32
	nodes    []node
	free     int32 // head of the free list, chained through node.next
	head     int32 // most recently used
	tail     int32 // least recently used
	capacity int
}

// New returns an empty cache holding at most capacity keys. sizeHint is the
// expected peak number of entries and is used only to preallocate storage.
// New panics if capacity is less than 1.
func New(capacity, sizeHint int) *Cache {
	if capacity < 1 {
		panic("lru: capacity must be at least 1")
	}
	sizeHint = max(0, min(sizeHint, capacity))
	return &Cache{
		index:    make(map[string]int32, sizeHint),
		nodes:    make([]node, 0, sizeHint),
		free:     nilIndex,
		head:     nilIndex,
		tail:     nilIndex,
		capacity: capacity,
	}
}

// Len reports the number of keys held.
func (c *Cache) Len() int { return len(c.index) }

// Get returns the value stored for key and marks key as the most recently
// used. The boolean reports whether the key was present.
func (c *Cache) Get(key string) (string, bool) {
	i, ok := c.index[key]
	if !ok {
		return "", false
	}
	c.touch(i)
	return c.nodes[i].value, true
}

// Set inserts or overwrites key and marks it as the most recently used. If
// the cache then holds more than its capacity, the least recently used key
// is evicted.
func (c *Cache) Set(key, value string) {
	if i, ok := c.index[key]; ok {
		c.nodes[i].value = value
		c.touch(i)
		return
	}
	if len(c.index) == c.capacity {
		c.remove(c.tail)
	}
	i := c.alloc()
	c.nodes[i] = node{key: key, value: value}
	c.index[key] = i
	c.pushFront(i)
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key string) bool {
	i, ok := c.index[key]
	if !ok {
		return false
	}
	c.remove(i)
	return true
}

func (c *Cache) alloc() int32 {
	if i := c.free; i != nilIndex {
		c.free = c.nodes[i].next
		return i
	}
	c.nodes = append(c.nodes, node{})
	return int32(len(c.nodes) - 1)
}

// remove unlinks node i, drops it from the index and recycles its slot.
func (c *Cache) remove(i int32) {
	c.unlink(i)
	delete(c.index, c.nodes[i].key)
	c.nodes[i] = node{next: c.free} // release strings for the GC
	c.free = i
}

func (c *Cache) touch(i int32) {
	if c.head == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

func (c *Cache) unlink(i int32) {
	n := &c.nodes[i]
	if n.prev != nilIndex {
		c.nodes[n.prev].next = n.next
	} else {
		c.head = n.next
	}
	if n.next != nilIndex {
		c.nodes[n.next].prev = n.prev
	} else {
		c.tail = n.prev
	}
}

func (c *Cache) pushFront(i int32) {
	n := &c.nodes[i]
	n.prev = nilIndex
	n.next = c.head
	if c.head != nilIndex {
		c.nodes[c.head].prev = i
	} else {
		c.tail = i
	}
	c.head = i
}

package lru

import "testing"

func TestEvictionOrder(t *testing.T) {
	c := New(2, 2)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf("Get(a) = %q, %v; want 1, true", v, ok)
	}
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
	if c.Len() != 2 {
		t.Fatalf("Len = %d; want 2", c.Len())
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	c := New(2, 0)
	c.Set("a", "1")
	c.Set("b", "2")
	c.Set("a", "9")
	c.Set("c", "3")
	if v, _ := c.Get("a"); v != "9" {
		t.Fatalf("Get(a) = %q; want 9", v)
	}
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
}

func TestDeleteReusesSlots(t *testing.T) {
	c := New(3, 3)
	for range 10 {
		c.Set("x", "1")
		c.Set("y", "2")
		if !c.Delete("x") || c.Delete("x") {
			t.Fatal("Delete(x) should succeed exactly once")
		}
		if !c.Delete("y") {
			t.Fatal("Delete(y) should succeed")
		}
	}
	if c.Len() != 0 || len(c.nodes) != 2 {
		t.Fatalf("Len = %d, pool = %d; want 0, 2", c.Len(), len(c.nodes))
	}
}

// Command app simulates an LRU cache driven by commands on standard input.
//
// The first line holds the capacity; each later line is one of
// SET <key> <value>, GET <key>, DEL <key> or SIZE. See SPEC.md.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"lru/internal/lru"
)

const maxCapacity = 1_000_000

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "lru:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	data, err := io.ReadAll(r)
	if err != nil {
		return fmt.Errorf("read: %w", err)
	}
	if len(data) == 0 {
		return nil
	}
	// One conversion up front lets every key and value be a zero-copy
	// substring of the input.
	input := string(data)

	first, rest := nextLine(input)
	capacity := parseCapacity(first)
	lines := strings.Count(rest, "\n") + 1
	cache := lru.New(capacity, lines)

	out := bufio.NewWriterSize(w, 64<<10)
	for len(rest) > 0 {
		var line string
		line, rest = nextLine(rest)
		execute(cache, out, line)
	}
	if err := out.Flush(); err != nil {
		return fmt.Errorf("write: %w", err)
	}
	return nil
}

// nextLine splits off the first line of s, dropping the "\n" terminator and
// a trailing "\r".
func nextLine(s string) (line, rest string) {
	line, rest, _ = strings.Cut(s, "\n")
	return strings.TrimSuffix(line, "\r"), rest
}

// parseCapacity reads a leading integer the way C's strtol does (optional
// leading whitespace and sign, then digits, ignoring anything after) and
// clamps it to [1, maxCapacity].
func parseCapacity(s string) int {
	s = strings.TrimLeft(s, " \t\v\f\r")
	neg := false
	if s != "" && (s[0] == '+' || s[0] == '-') {
		neg = s[0] == '-'
		s = s[1:]
	}
	n := 0
	for i := 0; i < len(s) && '0' <= s[i] && s[i] <= '9'; i++ {
		n = min(n*10+int(s[i]-'0'), maxCapacity+1) // saturate to avoid overflow
	}
	if neg {
		n = -n
	}
	return max(1, min(n, maxCapacity))
}

// nextToken returns the next space-delimited token of s and the remainder.
func nextToken(s string) (tok, rest string) {
	s = strings.TrimLeft(s, " ")
	if i := strings.IndexByte(s, ' '); i >= 0 {
		return s[:i], s[i:]
	}
	return s, ""
}

// execute runs one command line. Malformed or unknown commands are ignored.
func execute(c *lru.Cache, out *bufio.Writer, line string) {
	cmd, line := nextToken(line)
	if cmd == "SIZE" {
		out.Write(strconv.AppendInt(out.AvailableBuffer(), int64(c.Len()), 10))
		out.WriteByte('\n')
		return
	}
	key, line := nextToken(line)
	if key == "" {
		return
	}
	switch cmd {
	case "GET":
		if v, ok := c.Get(key); ok {
			out.WriteString(v)
		} else {
			out.WriteString("NULL")
		}
		out.WriteByte('\n')
	case "DEL":
		if c.Delete(key) {
			out.WriteString("1\n")
		} else {
			out.WriteString("0\n")
		}
	case "SET":
		if value, _ := nextToken(line); value != "" {
			c.Set(key, value)
		}
	}
}
